// Originally generated by `archegraph testgen`, then HAND-REPAIRED so it
// typechecks. Regenerating this file discards those repairs.

import { describe, expect, test } from 'bun:test';
import * as fc from 'fast-check';

import { contextMenuItems } from '../src/shell/menu_items';

describe('testgen_shell__contextMenuItems', () => {
    const makeCommand = (id: string, appliesTo?: 'global' | Array<'node' | 'edge' | 'group' | 'annotation'>): Parameters<typeof contextMenuItems>[1][number] => ({ id: id as Parameters<typeof contextMenuItems>[1][number]['id'], label: id, run: () => {}, ...(appliesTo === undefined ? {} : { appliesTo }) } as Parameters<typeof contextMenuItems>[1][number]);

    const makeElement = (kind: 'node' | 'edge' | 'group' | 'annotation', id: string): Parameters<typeof contextMenuItems>[0][number] => ({ id, kind } as Parameters<typeof contextMenuItems>[0][number]);

    const makeKeymap = (command: string, key: 'ArrowUp' | 'ArrowDown' | 'ArrowLeft' | 'ArrowRight' | 'Escape' | 'x' | 'q'): Parameters<typeof contextMenuItems>[2][number] => ({ command: command as Parameters<typeof contextMenuItems>[2][number]['command'], chord: { key } } as Parameters<typeof contextMenuItems>[2][number]);

    test('empty_selection_keeps_global_commands', () => {
        fc.assert(
            fc.property(fc.array(fc.constantFrom('global', 'absent', 'node', 'edge', 'group', 'annotation')), (value) => {
        const commands = value.map((tag: 'global' | 'absent' | 'node' | 'edge' | 'group' | 'annotation', index: number) => makeCommand(String(index), tag === 'absent' ? undefined : tag === 'global' ? 'global' : [tag]));
        const items = contextMenuItems([], commands, []);
        expect(items.map((item: { id: unknown }) => item.id)).toEqual(commands.filter((command: { appliesTo?: unknown }) => command.appliesTo === 'global').map((command: { id: unknown }) => command.id));
            })
        );
    });

    test('global_command_applies_to_any_selection', () => {
        fc.assert(
            fc.property(fc.array(fc.constantFrom('node', 'edge', 'group', 'annotation')), (value) => {
        const selection = value.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, String(index)));
        const items = contextMenuItems(selection, [makeCommand('global', 'global')], []);
        expect(items.map((item: { id: unknown }) => item.id)).toEqual(['global']);
            })
        );
    });

    test('single_kind_selection_matches_kind_list', () => {
        fc.assert(
            fc.property(fc.array(fc.constantFrom('node', 'edge', 'group', 'annotation'), { minLength: 1 }), (value) => {
        const selection = value.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, String(index)));
        const items = contextMenuItems(selection, [makeCommand('matching', [value[0]])], []);
        expect(items.map((item: { id: unknown }) => item.id)).toEqual(['matching']);
            })
        );
    });

    test('mixed_selection_uses_any_kind_match', () => {
        fc.assert(
            fc.property(fc.uniqueArray(fc.constantFrom('node', 'edge', 'group', 'annotation'), { minLength: 2 }), (value) => {
        const selection = value.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, String(index)));
        const items = contextMenuItems(selection, [makeCommand('partial-match', [value[0]])], []);
        expect(items.map((item: { id: unknown }) => item.id)).toEqual(['partial-match']);
            })
        );
    });

    test('nonmatching_kind_list_is_excluded', () => {
        fc.assert(
            fc.property(fc.tuple(fc.constantFrom('node', 'edge', 'group', 'annotation'), fc.constantFrom('node', 'edge', 'group', 'annotation')).filter((pair: readonly ['node' | 'edge' | 'group' | 'annotation', 'node' | 'edge' | 'group' | 'annotation']) => pair[0] !== pair[1]), (value) => {
        const selection = [makeElement(value[0], 'selected')];
        const items = contextMenuItems(selection, [makeCommand('nonmatch', [value[1]])], []);
        expect(items).toEqual([]);
            })
        );
    });

    test('absent_applies_to_is_excluded', () => {
        fc.assert(
            fc.property(fc.array(fc.constantFrom('node', 'edge', 'group', 'annotation')), (value) => {
        const selection = value.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, String(index)));
        const items = contextMenuItems(selection, [makeCommand('keyboard-only')], []);
        expect(items).toEqual([]);
            })
        );
    });

    test('commands_retain_input_order', () => {
        fc.assert(
            fc.property(fc.uniqueArray(fc.string({ minLength: 1 }), { minLength: 2 }), (value) => {
        const commands = value.map((id: string) => makeCommand(id, 'global'));
        const items = contextMenuItems([], commands, []);
        expect(items.map((item: { id: unknown }) => item.id)).toEqual(value);
            })
        );
    });

    test('selection_change_does_not_reorder_survivors', () => {
        fc.assert(
            fc.property(fc.record({ first: fc.array(fc.constantFrom('node', 'edge', 'group', 'annotation')), second: fc.array(fc.constantFrom('node', 'edge', 'group', 'annotation')), commands: fc.array(fc.constantFrom('global', 'node', 'edge', 'group', 'annotation'), { minLength: 1 }) }), (value) => {
        const firstSelection = value.first.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, `first-${index}`));
        const secondSelection = value.second.map((kind: 'node' | 'edge' | 'group' | 'annotation', index: number) => makeElement(kind, `second-${index}`));
        const commands = value.commands.map((tag: 'global' | 'node' | 'edge' | 'group' | 'annotation', index: number) => makeCommand(String(index), tag === 'global' ? 'global' : [tag]));
        const firstItems = contextMenuItems(firstSelection, commands, []);
        const secondItems = contextMenuItems(secondSelection, commands, []);
        const firstIds = firstItems.map((item: { id: unknown }) => item.id);
        const secondIds = secondItems.map((item: { id: unknown }) => item.id);
        const applicable = (selection: ReadonlyArray<{ kind: 'node' | 'edge' | 'group' | 'annotation' }>, tag: 'global' | 'node' | 'edge' | 'group' | 'annotation'): boolean => tag === 'global' || (selection.length > 0 && selection.some((element: { kind: 'node' | 'edge' | 'group' | 'annotation' }) => element.kind === tag));
        expect(firstIds).toEqual(value.commands.map((_: 'global' | 'node' | 'edge' | 'group' | 'annotation', index: number) => String(index)).filter((_: string, index: number) => applicable(firstSelection, value.commands[index])));
        expect(secondIds).toEqual(value.commands.map((_: 'global' | 'node' | 'edge' | 'group' | 'annotation', index: number) => String(index)).filter((_: string, index: number) => applicable(secondSelection, value.commands[index])));
            })
        );
    });

    // WHEN: No commands are supplied; the result is an empty array.
    // THEN: With no commands supplied, it returns an empty array.
    test('empty_command_list_returns_empty', () => {
        expect(contextMenuItems([], [], [])).toEqual([]);
    });

    test('no_applicable_commands_returns_empty', () => {
        fc.assert(
            fc.property(fc.array(fc.string({ minLength: 1 })), (value) => {
        const commands = value.map((id: string) => makeCommand(id));
        expect(contextMenuItems([], commands, [])).toEqual([]);
            })
        );
    });

    test('keymap_data_formats_command_chords', () => {
        fc.assert(
            fc.property(fc.array(fc.constantFrom('ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Escape', 'x', 'q'), { minLength: 1 }).map((keys: readonly ('ArrowUp' | 'ArrowDown' | 'ArrowLeft' | 'ArrowRight' | 'Escape' | 'x' | 'q')[]) => [keys[0]] as const), (value) => {
        const command = makeCommand('bound', 'global');
        const keymap = [makeKeymap('bound', value[0])];
        const items = contextMenuItems([], [command], keymap);
        const expected = value[0] === 'ArrowUp' ? 'Up' : value[0] === 'ArrowDown' ? 'Down' : value[0] === 'ArrowLeft' ? 'Left' : value[0] === 'ArrowRight' ? 'Right' : value[0] === 'Escape' ? 'Esc' : value[0].toUpperCase();
        expect(items).toHaveLength(1);
        expect(items[0].chord).toBe(expected);
            })
        );
    });

});

